//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//

//----W-Craft WebSquare 변환 확인: include----//
scwin.vScrenID = 'ULDMGT10203.gfm';

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.MxDataSet_OnLoadCompleted = function(rowcount) {
    textbox_1.setValue("총 " + rowcount + "건");
};

scwin.MxDataSet_info_OnLoadCompleted = function(rowcount) {
    textbox_2.setValue("총 " + rowcount + "건");
};

scwin.btn_cal_onclick = function(e) {

    //----W-Craft WebSquare 변환 확인: popUpCalendar----//
    popUpCalendar(txb_date_bg, 'txb_date', 'yyyymmdd'); //alert('image_2.onclick');

};

scwin.btn_sys_search_onclick = function(e) {
    if (txb_date.getValue() !== "") {
        scwin.listSync(); //alert();

    } else {
        alert("접수일자를 지정하십시요");
    }
};

scwin.MxGrid_1_OnClick = function(row, colid) {

    //----W-Craft WebSquare 변환 확인: NameValue----//
    const sCd = MxDataSet.NameValue(row, "DISCLS_DOC_NO");
    scwin.infoSync(sCd);
};

scwin.btn_toExcel_onclick = function(e) {

    //----W-Craft WebSquare 변환 확인: GridToExcel----//
    MxGrid_1.GridToExcel("추출대상문서", "", "8");
};

scwin.image_1_onclick = function(e) {

    //----W-Craft WebSquare 변환 확인: GridToExcel----//
    MxGrid_2.GridToExcel("추출대상문서상세정보", "", "8");
};

///////// 5. 일반/업무 함수 영역 /////////
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/extdoc.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

scwin.infoSync = async function(sval) {
    const sbmOptions = {
        id : "sbm_MxDataSet_info",
        action : "/extinfo.do",
        ref : "",
        target : "MxDataSet_info=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

scwin.gform_onload = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_MxDataSet_info",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_info=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    $c.libRoundPanel.PanelToGroupBox_01(panel_1);
    //PanelToGroupBox_02(panel_2);

    //----W-Craft WebSquare 변환 확인: toDaySet----//
    toDaySet(txb_date);
};
